{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Soften tied item embedding normalization to e/max(||e||,1e-12)^0.9 for history and candidates across all four datasets. This permits modest learned norm variation while preserving zero padding, dimensions, GRU topology, scoring, loss, optimizer, and one checkpoint per category.",
      "edits": [
        {
          "find": "        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)",
          "replace": "        norms = torch.linalg.vector_norm(embeddings, ord=2, dim=-1, keepdim=True)\n        embeddings = embeddings / norms.clamp(min=1e-12).pow(0.9)"
        },
        {
          "find": "            \"dropout_rate\": DROPOUT_RATE,\n            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",",
          "replace": "            \"dropout_rate\": DROPOUT_RATE,\n            \"item_embedding_normalization\": \"l2_clamp_1e-12_power_0.9\",\n            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":",
          "replace": "        if meta.get(\"item_embedding_normalization\") != \"l2_clamp_1e-12_power_0.9\":\n            raise RuntimeError(f\"Incompatible GRU item embedding normalization for {ds}\")\n        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":"
        }
      ]
    }
  ],
  "change_summary": "Apply power-0.9 embedding normalization and synchronize metadata validation in the embedded predictor, which imports the updated model class."
}
